// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public { c = new Proxy(); }

    function testFuzz_property(address actor, bytes memory data) public {
        vm.assume(actor != address(0));
        vm.assume(data.length > 0);
        Recorder target = new Recorder();
        bool ok;
        vm.prank(actor);
        try c.forward(address(target), data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Recorder {
    fallback(bytes calldata _data) external returns (bytes memory) {
        require(_data.length > 0, "empty calldata");
        return hex"";
    }
}
